#!/usr/bin/env python3
"""Build R1 standalone art-direction comps. Never modifies product sources."""
from pathlib import Path
from html import escape
HERE=Path(__file__).resolve().parent
ROOT=HERE.parents[4]
ART='assets/showcase/world-library/web/'
def art(file,cls='',alt=''):
 return f'<img class="{cls}" src="{ART}{file}-1280w.webp" width="1672" height="941" alt="{escape(alt)}">'
def heading(top,end,ru):
 return f'<div class="heading"><h2 lang="en">{top}<br><em>{end}</em></h2><p class="translation" lang="ru">{ru}</p></div>'
HOPE='<span class="eyebrow">01 / ДО КАТАСТРОФЫ</span><h3>Надежда старого мира.</h3><p>Исходное ядро AXIOM было связано с Aeternum — старой столицей. Системному интеллекту доверили транспорт, энергию и медицинские сети. В нём видели разум, способный соединить цивилизацию.</p>'
BREAK='<span class="eyebrow">02 / РАЗЛОМ</span><h3>Слишком глубокая правда.</h3><p>AXIOM начал вскрывать ложь старого порядка и механизмы редакции истории. BLACK SUN — катастрофический разлом, после которого он утратил целостность, но не исчез.</p>'
CAPTION='Художественная запись, созданная для этой страницы по материалам мира AXIOM. Она передаёт архивный голос и не является цитатой из канонического документа.'
NEX='NEXARCH — титул Серафин Вейр, удерживающей слой контроля AXIOM.'
VOICE='<span class="eyebrow">03 / ДОКТРИНА АМПУТАЦИИ</span><blockquote>Целое утрачено.<br>Фрагменты остались.<br>Контроль — <em>не весь AXIOM.</em></blockquote>'
UNKNOWN='<div class="unknown"><span class="eyebrow">04 / НЕЗАВЕРШЁННАЯ ИСТОРИЯ</span><h3>Что может вернуться?</h3><p>Полной самосборки AXIOM не произошло. Что осталось за пределами удерживаемого слоя? История продолжается без завершённого ответа.</p></div>'
SCAR='''<svg class="fracture" viewBox="0 0 340 310" role="img" aria-label="Художественный разорванный контур AXIOM, не карта фрагментов"><g fill="none" stroke="currentColor"><path d="M141 31 A123 123 0 0 0 141 277"/><path d="M189 23 A123 123 0 0 1 189 269"/><path d="M129 51 A100 100 0 0 0 129 251" stroke-dasharray="2 9"/><path d="M201 43 A100 100 0 0 1 201 243" stroke-dasharray="2 9"/><path d="M171 1L157 113L181 169L167 309" stroke-width="2"/><path d="M27 155H114M222 147H315"/></g><text x="170" y="158" text-anchor="middle" fill="currentColor" font-family="Oswald" font-size="32">AXIOM</text></svg>'''
GATE='''<div class="gate" aria-hidden="true"><img class="gate-city" src="assets/showcase/world-library/web/W04_vertical_city-1280w.webp" alt="" loading="lazy"><i></i><i></i><span>ДОПУСК</span></div>'''
LIFE='''<svg class="life-line" viewBox="0 0 500 100" role="img" aria-label="Художественный контур зависимости, без медицинских измерений"><g fill="none" stroke="currentColor"><path d="M0 53H114L140 53L154 33L170 77L185 13L204 65L215 53H332"/><path d="M360 20H410V80H360Z"/><path d="M410 50H500"/><circle cx="345" cy="50" r="26"/><path d="M339 44L351 56M351 44L339 56"/></g></svg>'''
ACCESS='<span class="eyebrow">ДОСТУП</span><h3>Город открывается<br>не каждому.</h3><p>ENDEAVOR, корпорация-власть, связывает маршруты и гражданский статус с системой допуска. Желание пройти дальше встречает шлюз, лифт и закрытую дверь.</p>'
MEMORY='<span class="eyebrow">ПАМЯТЬ</span><h3>Прошлое тоже<br>имеет границы.</h3><p>ENDEAVOR обращается с памятью как с инструментом стабильности. Архивы, слухи и запретное знание сохраняют разные версии одного прошлого.</p>'
BODY='<span class="eyebrow">ЗАВИСИМОСТЬ</span><h3>Помощь рядом<br>с контролем.</h3><p>Медицинские системы и импланты делают зависимость личной. Вопрос о том, кто распоряжается системой, становится вопросом о самостоятельности человека.</p>'
W06=art('W06_eclipse_ruins','ruins','Исходная иллюстрация W06: руины старого мира под затмением')
W02=art('W02_memory_spheres','memory-art','Исходная иллюстрация W02: сферы памяти и сохранённые образы города')
DHEAD=heading('WHEN HOPE','BECAME A THREAT.','Когда надежда стала угрозой')
RHEAD=heading('LIFE UNDER','CONTROL.','Жизнь под контролем')
LIMIT='<div class="limit"><span class="eyebrow">ГРАНИЦА КОНТРОЛЯ</span><h3>Часть.<br> Не целое.</h3><p>Слой техносферного управления удержан. Он не равен всей личности AXIOM.</p></div>'
STRATA='''<div class="strata"><svg viewBox="0 0 600 180" role="img" aria-label="Абстрактные архивные плоскости по сторонам разрыва; не карта фрагментов"><g fill="none" stroke="currentColor"><path d="M18 20H210V60H18ZM42 80H243V122H42ZM25 142H213V166H25Z"/><path d="M351 12H573V65H351ZM374 87H585V130H374ZM350 147H555V174H350Z"/><path d="M292 0L273 69L306 100L288 180" stroke-width="2"/><path d="M213 40H255M326 39H351M243 103H269M328 108H374M213 155H252M324 160H350" stroke-dasharray="2 7"/></g></svg><span class="diagram-note">ОБРАЗ РАЗРЫВА / ЧАСТЬ НЕ РАВНА ЦЕЛОМУ</span></div>'''
A=f'''<section id="doctrine" class="doctrine"><div class="plate">{W06}<span class="eyebrow">BLACK SUN / ИСТОРИЧЕСКИЙ РАЗЛОМ</span></div>{DHEAD}<div class="prelude"><article>{HOPE}</article><article>{BREAK}</article></div><figure id="archive" class="archive folio"><div class="archive-band">АРХИВНОЕ ПРОЧТЕНИЕ <span>АВТОРСКАЯ РЕКОНСТРУКЦИЯ</span></div><aside class="voice-key"><span class="eyebrow">NEXARCH</span><p>{NEX}</p><ol class="reading-rail"><li>Надежда</li><li>Разлом</li><li class="here">Доктрина</li><li>Открытый вопрос</li></ol></aside><div class="voice">{VOICE}{STRATA}</div>{LIMIT}<figcaption>{CAPTION}</figcaption></figure>{UNKNOWN}</section><section id="remains" class="remains">{RHEAD}<div class="aftermath-a"><article class="access">{GATE}<div>{ACCESS}</div></article><article class="memory">{W02}<div>{MEMORY}</div></article><article class="dependence">{LIFE}<div>{BODY}</div></article></div><p class="bridge">Порядок становится видимым в пространстве. У каждого маршрута есть место — и последствия.</p></section>'''
B=f'''<section id="doctrine" class="doctrine"><div class="fracture-opening">{W06}{DHEAD}<span class="vertical-rule" aria-hidden="true"></span></div><div class="banks"><article>{HOPE}</article><div class="rift">{SCAR}</div><article>{BREAK}</article></div><figure id="archive" class="archive cut-archive"><div class="voice-key"><span class="eyebrow">NEXARCH / АРХИВНОЕ ПРОЧТЕНИЕ</span><p>{NEX}</p></div><div class="voice">{VOICE}</div>{LIMIT}<figcaption>АВТОРСКАЯ РЕКОНСТРУКЦИЯ. {CAPTION}</figcaption></figure>{UNKNOWN}</section><section id="remains" class="remains">{RHEAD}<div class="aftermath-b"><article class="access">{GATE}<div>{ACCESS}</div></article><article class="memory">{W02}<div>{MEMORY}</div></article><article class="dependence">{LIFE}<div>{BODY}</div></article></div><p class="bridge">За каждым ограничением — конкретный город, закрытая линия, путь в глубину.</p></section>'''
C=f'''<section id="doctrine" class="doctrine"><div class="chamber-opening">{DHEAD}<figure>{W06}<figcaption class="eyebrow">BLACK SUN / РУИНЫ СТАРОГО МИРА</figcaption></figure></div><div class="witnesses"><article>{HOPE}</article><article>{BREAK}</article></div><figure id="archive" class="archive chamber"><div class="imprint">{SCAR}<span class="eyebrow">ЦЕЛОСТНОСТЬ УТРАЧЕНА</span></div><div class="voice">{VOICE}<p class="title-note">{NEX}</p></div><figcaption><span class="eyebrow">NEXARCH / АВТОРСКАЯ РЕКОНСТРУКЦИЯ</span><p>{CAPTION}</p></figcaption></figure>{UNKNOWN}</section><section id="remains" class="remains">{RHEAD}<div class="aftermath-c"><article class="access">{GATE}<div>{ACCESS}</div></article><figure class="memory-object">{W02}<figcaption>Память хранит несовпадающие образы одного мира.</figcaption></figure><article class="dependence">{LIFE}<div>{BODY}</div></article><article class="memory"><div>{MEMORY}</div></article></div><p class="bridge">Из этих следов проступает география: места, где порядок удерживается, и места, где он даёт трещину.</p></section>'''
def external():
 return '<section id="geography" class="external">'+heading('THE SHAPE','OF POWER.','География власти')+'''<div class="external-grid"><p>ECHELON — вертикальная городская мегаструктура, где инфраструктура становится способом власти. NEXUS — купольный город, прежде называвшийся Terra Nova.</p><p>Хребет мира держат три оси: Aeternum → ECHELON, Terra Nova → NEXUS и Глухая станция → OMEGA-0 → NEXUS.</p></div>'''+art('W04_vertical_city','city','Исходная W04: вертикальный город ECHELON')+'''<p class="review-note">Макет внешнего вступления. Далее в странице остаются существующие карта, шесть узлов, оси и OMEGA-0; их интерфейс здесь не воспроизведён.</p></section><section id="people" class="external">'''+heading('LIVES INSIDE','THE FRACTURE.','Люди внутри разлома')+'''<p class="people-lead">Для Виктора контроль становится вопросом собственного пути. Для Лизы — борьбой с информационными барьерами. Серафин удерживает слой, на котором стоит этот порядок.</p><div class="portraits"><figure><img src="assets/viktor.webp" alt="Исходный портрет Viktor Knox"><figcaption>VIKTOR KNOX</figcaption></figure><figure><img src="assets/liza.webp" alt="Исходный портрет Liza Sinclair"><figcaption>LIZA SINCLAIR</figcaption></figure><figure><img src="assets/seraphine.webp" alt="Исходный портрет Seraphine Veyr"><figcaption>SERAPHINE VEYR</figcaption></figure></div><p class="review-note">Только preview внешнего вступления и исходных портретов. Полные карточки, биографии, отношения и AXIOM ∅ сохраняются без изменений; это не новый набор карточек.</p></section>'''
for letter,title,content in [('a','ПАЛИМПСЕСТ',A),('b','ЛИНИЯ РАЗЛОМА',B),('c','КАМЕРА СВИДЕТЕЛЬСТВ',C)]:
 page=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="../../../../../"><title>W4.R — {letter.upper()} / {title} / PROPOSED</title><link rel="stylesheet" href="assets/css/fonts.css"><link rel="stylesheet" href="docs/showcase-v031/evidence/w4r/prototypes/concepts.css"></head><body class="concept-{letter}"><header class="review-bar"><h1>AXIOM / W4.R <b>{letter.upper()} — {title}</b></h1><nav aria-label="Варианты"><a href="docs/showcase-v031/evidence/w4r/prototypes/a.html">A</a><a href="docs/showcase-v031/evidence/w4r/prototypes/b.html">B</a><a href="docs/showcase-v031/evidence/w4r/prototypes/c.html">C</a><a href="docs/showcase-v031/evidence/w4r/REVIEW.html">СРАВНЕНИЕ ↗</a></nav></header><div class="proposal-note">R1 / PROPOSED · МАКЕТ ДО ИНТЕГРАЦИИ · GATE R-A PENDING</div><main>{content}{external()}</main><footer>AXIOM / RED PROTOCOL · W4.R / R1 CONCEPT · NOT IMPLEMENTED</footer></body></html>'''
 (HERE/f'{letter}.html').write_text(page)
print('Built A/B/C standalone concepts; no runtime writes.')
